  function budgetChartData(b){
    const nodes=list(b?.nodes),total=cents(b?.totalCents);
    if(b?.reconciled!==true||total===null||total===0||!nodes.length||nodes.some(n=>cents(n.totalCents)===null))return null;
    const sum=nodes.reduce((a,n)=>a+n.totalCents,0);
    if(!Number.isSafeInteger(sum)||sum!==total)return null;
    // Root totals already contain their children. Never count descendants again.
    const ranked=nodes.map(n=>({id:n.id,title:n.title||'Etapa',value:n.totalCents,percent:n.totalCents/total*100})).sort((a,b)=>b.value-a.value);
    const segments=ranked.length>8?[...ranked.slice(0,7),{id:'chart-others',title:'Demais etapas',value:ranked.slice(7).reduce((a,n)=>a+n.value,0),percent:ranked.slice(7).reduce((a,n)=>a+n.percent,0)}]:ranked;
    return {total,ranked,segments};
  }
  function paymentMetric(project){
    if(!project.modules?.includes('payments'))return null;
    const p=project.payments;
    if(!['complete','partial'].includes(p?.coverage)||!Number.isSafeInteger(p.receivedCents))return {label:'Pagamentos',value:'A conferir',note:'Registros ainda não confirmados'};
    return {label:'Pagamentos líquidos',value:money(p.receivedCents),note:p.coverage==='partial'?'Registros parciais · saldo não apurado':'Registros completos'+(date(p.asOf)?` até ${date(p.asOf)}`:'')};
  }
