    const colors=['#DFCA8F','#B69A60','#F1EEE6','#A8A29A','#88745B','#CEB6A3','#7D8DAB','#B2B0BC'];
    const figure=document.createElement('figure');figure.className='donut-figure';
    const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 240 240');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');
    let offset=0;
