    const rid=++state.request;state.controller?.abort();const controller=new AbortController();state.controller=controller;
    state.role=null;state.projects=[];state.project=null;state.projectId=null;state.admin=null;state.etag=null;state.revision=null;$('#request-form').hidden=true;gate('Conferindo sua autorização…');
