  async function requestAccess(e){e.preventDefault();const name=$('#request-name').value.trim();const sid=state.sessionId;if(name.length<2){gate('Informe seu nome para solicitar acesso.',{title:'Solicitar acesso',request:true});return}const submit=e.submitter;submit.disabled=true;try{await api(API,{method:'POST',body:{action:'request-access',displayName:name},sessionId:sid});if(sid!==state.sessionId)return;gate('Sua solicitação foi registrada e aguarda análise.',{title:'Acesso solicitado',actions:[['retry','Verificar acesso'],['logout','Sair da conta']]})}catch(err){if(sid===state.sessionId)gate(err.message||'Não foi possível solicitar acesso. Tente novamente.',{title:'Solicitar acesso',request:true})}finally{if(sid===state.sessionId)submit.disabled=false}}
